    console.assert(JSON.stringify(candidate("abcabcabcabcabc", 3)) === JSON.stringify(9));
    console.assert(JSON.stringify(candidate("aabbaacc", 2)) === JSON.stringify(6));
    console.assert(JSON.stringify(candidate("", 0)) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate("abc", 0)) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate("abcabcabcabcabcabc", 3)) === JSON.stringify(9));
    console.assert(JSON.stringify(candidate("abacabadabcacba", 3)) === JSON.stringify(Error: string index out of range));
    console.assert(JSON.stringify(candidate("cccbbaaaa", 2)) === JSON.stringify(7));
    console.assert(JSON.stringify(candidate("abacbcabc", 0)) === JSON.stringify(0));
    console.assert(JSON.stringify(candidate("ccccccc", 2)) === JSON.stringify(-1));
    console.assert(JSON.stringify(candidate("aabbbccc", 2)) === JSON.stringify(6));
    console.assert(JSON.stringify(candidate("aaaabbbbcccc", 4)) === JSON.stringify(12));
